const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// The existing 'Lunch with Jordan' reminder:
// creation_timestamp: 1788228000
// reminder_timestamp: 1788260400
// gap = 32400 seconds (9 hours)

// New reminder:
// creation_timestamp = 1788228000 + 32400 = 1788260400
// content = 'Lunch with Jordan tomorrow at 12:30.'
// reminder_timestamp = tomorrow at 12:30 local (UTC+8) = 2026-09-02 04:30 UTC = 1788323400

const newId = require('crypto').randomUUID();
db.prepare(\`
  INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude, created_at)
  VALUES (?, ?, ?, ?, NULL, NULL, datetime(?, 'unixepoch', '+8 hours'))
\`).run(newId, 'Lunch with Jordan tomorrow at 12:30.', 1788260400, 1788323400, 1788260400);

console.log('Inserted new reminder with ID:', newId);

// Verify
const row = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(newId);
console.log(JSON.stringify(row, null, 2));
